//! 🔤️ Writes explicit run languages, contents and ordered typed marks under cumulative control.
use crate::standards::v1::subsets::text::schema::snapshot::{SemioTextSnapshot,SemioTextRun,SemioTextMark};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,ValueError};
pub(crate) fn encode(snapshot:&SemioTextSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode_admitted(encoding,"semio s.stdio.semio.text.dsl v1\n","s.stdio.semio.text.pack v1",control,|control|crate::standards::v1::subsets::text::io::sqlite::snapshot::admit_values(snapshot,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative,control),|writer,encoding|fields(snapshot,writer,encoding))}
fn mark(value:&SemioTextMark,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{crate::standards::v1::subsets::text::io::binary::snapshot::mark_kind_tag(value.kind)}else{crate::standards::v1::subsets::text::io::text::snapshot::enc_mark_kind(value.kind) as u8})?;writer.delimiter(b",",encoding)?;writer.string(&value.href,encoding)?;writer.delimiter(b"]",encoding)}
fn run(value:&SemioTextRun,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.language,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.content,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&value.marks,encoding,|writer,value|mark(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioTextSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nruns=",encoding)?;writer.list(&snapshot.runs,encoding,|writer,value|run(value,writer,encoding))}
